            <div class="form-group">
                <label for="email">Email *</label>
                <input id="email" type="email" @bind="email" placeholder="Enter your email" />
            </div>
            <div class="form-group">
                <label for="phone">Phone *</label>
                <input id="phone" type="tel" @bind="phone" placeholder="Enter your phone number" />
            </div>
            <div class="form-group">
                <label for="address">Address *</label>
                <input id="address" type="text" @bind="address" placeholder="Enter your address" />
            </div>
            <div class="form-actions">
                <button class="btn-next" @onclick="NextFromPersonalInfo" disabled="@isProcessing">
                    @if (isProcessing)
                    {
                        <span>Validating...</span>
                    }
                    else
                    {
                        <span>Next</span>
                    }
                </button>
            </div>
        </div>
    }

    @* Step 2: Work History *@
    @if (currentStep == 1)
    {
        <div class="form-section">
            <h2>Work History</h2>
            @for (int i = 0; i < workEntries.Count; i++)
            {
                var index = i;
                <div class="work-entry">
                    <h3>Position @(index + 1)</h3>
                    @if (workEntries.Count > 1)
                    {
                        <button class="btn-remove" @onclick="() => RemoveWorkEntry(index)">Remove</button>
                    }
                    <div class="form-group">
                        <label>Company Name *</label>
                        <input type="text" @bind="workEntries[index].Company" placeholder="Company name" />
                    </div>
                    <div class="form-group">
                        <label>Job Title *</label>
                        <input type="text" @bind="workEntries[index].Title" placeholder="Job title" />
                    </div>
                    <div class="form-group">
                        <label>Start Date *</label>
                        <input type="date" @bind="workEntries[index].StartDate" />
                    </div>
                    <div class="form-group">
                        <label>
                            <input type="checkbox" @bind="workEntries[index].IsCurrent" /> Currently working here
                        </label>
                    </div>
                    @if (!workEntries[index].IsCurrent)
                    {
                        <div class="form-group">
                            <label>End Date</label>
                            <input type="date" @bind="workEntries[index].EndDate" />
                        </div>
                    }
                    <div class="form-group">
                        <label>Description *</label>
                        <textarea @bind="workEntries[index].Description" placeholder="Describe your responsibilities"></textarea>
                    </div>
                </div>
            }
            <button class="btn-add" @onclick="AddWorkEntry">+ Add Another Position</button>
            <div class="form-actions">
                <button class="btn-back" @onclick="PreviousStep">Back</button>
                <button class="btn-next" @onclick="NextFromWorkHistory">Next</button>
            </div>
        </div>
    }

    @* Step 3: References *@
    @if (currentStep == 2)
    {
        <div class="form-section">
            <h2>References</h2>
            @for (int i = 0; i < references.Count; i++)
            {
                var index = i;
                <div class="reference-entry">
                    <h3>Reference @(index + 1)</h3>
                    @if (references.Count > 2)
                    {
                        <button class="btn-remove" @onclick="() => RemoveReference(index)">Remove</button>
                    }
                    <div class="form-group">
                        <label>Name *</label>
                        <input type="text" @bind="references[index].Name" placeholder="Reference name" />
                    </div>
                    <div class="form-group">
                        <label>Relationship *</label>
                        <input type="text" @bind="references[index].Relationship" placeholder="e.g., Former Manager" />
                    </div>
                    <div class="form-group">
                        <label>Email *</label>
                        <input type="email" @bind="references[index].Email" placeholder="Reference email" />
                    </div>
                    <div class="form-group">
                        <label>Phone *</label>
                        <input type="tel" @bind="references[index].Phone" placeholder="Reference phone" />
                    </div>
                </div>
            }
            @if (references.Count < 3)
            {
                <button class="btn-add" @onclick="AddReference">+ Add Reference</button>
            }
            <div class="form-actions">
                <button class="btn-back" @onclick="PreviousStep">Back</button>
                <button class="btn-next" @onclick="NextFromReferences">Next</button>
            </div>
        </div>
    }

    @* Step 4: Cover Letter *@
    @if (currentStep == 3)
    {
        <div class="form-section">
            <h2>Cover Letter</h2>
            <div class="form-group">
                <label for="coverLetter">Write your cover letter</label>
                <textarea id="coverLetter" class="cover-letter-input" @bind="coverLetter" @bind:event="oninput" maxlength="2000" placeholder="Write your cover letter here..."></textarea>
                <div class="character-count">@(coverLetter?.Length ?? 0) / 2000 characters</div>
            </div>
            <div class="form-actions">
                <button class="btn-back" @onclick="PreviousStep">Back</button>
                <button class="btn-next" @onclick="NextFromCoverLetter">Next</button>
            </div>
        </div>
    }

    @* Step 5: Review & Submit *@
    @if (currentStep == 4)
    {
        @if (isSubmitted)
        {
            <div class="form-section confirmation">
                <h2>Application Submitted!</h2>
                <p>Your application has been successfully submitted.</p>
                <p><strong>Application ID: @applicationId</strong></p>
            </div>
        }
        else
        {
            <div class="form-section">
                <h2>Review & Submit</h2>

                <div class="review-section">
                    <div class="review-header">
                        <h3>Personal Information</h3>
                        <a class="edit-link" @onclick='() => GoToStep(0)'>Edit</a>
                    </div>
                    <dl>
                        <dt>Full Name</dt><dd>@fullName</dd>
                        <dt>Email</dt><dd>@email</dd>
                        <dt>Phone</dt><dd>@phone</dd>
                        <dt>Address</dt><dd>@address</dd>
                    </dl>
                </div>

                <div class="review-section">
                    <div class="review-header">
                        <h3>Work History</h3>
                        <a class="edit-link" @onclick='() => GoToStep(1)'>Edit</a>
                    </div>
                    @foreach (var entry in workEntries)
                    {
                        <div class="review-work-entry">
                            <p><strong>@entry.Title</strong> at @entry.Company</p>
                            <p>@entry.StartDate.ToString("MMM yyyy") — @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy"))</p>
                            <p>@entry.Description</p>
                        </div>
                    }
                </div>

                <div class="review-section">
                    <div class="review-header">
                        <h3>References</h3>
                        <a class="edit-link" @onclick='() => GoToStep(2)'>Edit</a>
                    </div>
                    @foreach (var reference in references)
                    {
                        <div class="review-reference">
                            <p><strong>@reference.Name</strong> (@reference.Relationship)</p>
                            <p>@reference.Email | @reference.Phone</p>
                        </div>
                    }
                </div>

                <div class="review-section">
                    <div class="review-header">
                        <h3>Cover Letter</h3>
                        <a class="edit-link" @onclick='() => GoToStep(3)'>Edit</a>
                    </div>
                    <p class="cover-letter-preview">@coverLetter</p>
                </div>

                <div class="form-actions">
                    <button class="btn-back" @onclick="PreviousStep">Back</button>
                    <button class="btn-submit" @onclick="SubmitApplication" disabled="@isProcessing">
                        @if (isProcessing)
                        {
                            <span>Submitting...</span>
                        }
                        else
                        {
                            <span>Submit Application</span>
                        }
                    </button>
                </div>
            </div>
        }
    }
</div>

@code {
    private readonly string[] stepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };
    private int currentStep = 0;
    private bool isProcessing = false;
    private bool isSubmitted = false;
    private int applicationId;
    private string? errorMessage;

    // Step 1 fields
    private string fullName = "";
    private string email = "";
    private string phone = "";
    private string address = "";

    // Step 2 fields
    private List<WorkEntryModel> workEntries = new() { new WorkEntryModel() };

    // Step 3 fields
    private List<ReferenceModel> references = new() { new ReferenceModel(), new ReferenceModel() };

    // Step 4 fields
    private string coverLetter = "";

    private string GetStepClass(int stepIndex)
    {
        if (stepIndex == currentStep) return "active";
        if (stepIndex < currentStep) return "completed";
        return "future";
    }

    private void GoToStep(int step)
    {
        if (step < currentStep)
        {
            currentStep = step;
            errorMessage = null;
        }
    }

    private void PreviousStep()
    {
        if (currentStep > 0)
        {
            currentStep--;
            errorMessage = null;
        }
    }

    private async Task NextFromPersonalInfo()
    {
        errorMessage = null;

        if (string.IsNullOrWhiteSpace(fullName) || string.IsNullOrWhiteSpace(email) ||
            string.IsNullOrWhiteSpace(phone) || string.IsNullOrWhiteSpace(address))
        {
            errorMessage = "All fields are required.";
            return;
        }

        isProcessing = true;
        try
        {
            var isValidEmail = await ApplicationService.ValidateEmailAsync(email);
            if (!isValidEmail)
            {
                errorMessage = "The email address is not valid.";
                return;
            }
            currentStep++;
        }
        finally
        {
            isProcessing = false;
        }
    }

    private void NextFromWorkHistory()
    {
        errorMessage = null;

        foreach (var entry in workEntries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title) ||
                entry.StartDate == default || string.IsNullOrWhiteSpace(entry.Description))
            {
                errorMessage = "All work entry fields are required (company, title, start date, description).";
                return;
            }
        }

        currentStep++;
    }

    private void NextFromReferences()
    {
        errorMessage = null;

        foreach (var reference in references)
        {
            if (string.IsNullOrWhiteSpace(reference.Name) || string.IsNullOrWhiteSpace(reference.Relationship) ||
                string.IsNullOrWhiteSpace(reference.Email) || string.IsNullOrWhiteSpace(reference.Phone))
            {
                errorMessage = "All reference fields are required.";
                return;
            }
        }

        currentStep++;
    }

    private void NextFromCoverLetter()
    {
        errorMessage = null;

        if (string.IsNullOrWhiteSpace(coverLetter))
        {
            errorMessage = "Cover letter is required.";
            return;
        }

        currentStep++;
    }

    private async Task SubmitApplication()
    {
        isProcessing = true;
        errorMessage = null;

        try
        {
            var personal = new PersonalInfo(fullName, email, phone, address);
            var work = new WorkHistory(workEntries.Select(e => new WorkEntry(
                e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description
            )).ToList());
            var refs = references.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();
            var application = new JobApplication(personal, work, refs, coverLetter);

            applicationId = await ApplicationService.SubmitApplicationAsync(application);
            isSubmitted = true;
        }
        catch (Exception ex)
        {
            errorMessage = $"Submission failed: {ex.Message}";
        }
        finally
        {
            isProcessing = false;
        }
    }

    private void AddWorkEntry() => workEntries.Add(new WorkEntryModel());

    private void RemoveWorkEntry(int index)
    {
        if (workEntries.Count > 1)
            workEntries.RemoveAt(index);
    }

    private void AddReference()
    {
        if (references.Count < 3)
            references.Add(new ReferenceModel());
    }

    private void RemoveReference(int index)
    {
        if (references.Count > 2)
            references.RemoveAt(index);
    }

    private class WorkEntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime StartDate { get; set; }
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = "";
    }

    private class ReferenceModel
    {
        public string Name { get; set; } = "";
        public string Relationship { get; set; } = "";
        public string Email { get; set; } = "";
        public string Phone { get; set; } = "";
    }
}
"}

