toolArgs.file_text:
.application-form {
    max-width: 800px;
    margin: 0 auto;
    padding: 2rem;
}

.step-indicator {
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 2rem;
    gap: 0;
}

.step {
    display: flex;
    flex-direction: column;
    align-items: center;
    cursor: default;
    opacity: 0.4;
    transition: opacity 0.2s;
}

.step.active {
    opacity: 1;
}

.step.completed {
    opacity: 1;
    cursor: pointer;
}

.step.future {
    opacity: 0.4;
}

.step-circle {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    background: #e0e0e0;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
    font-size: 0.85rem;
    color: #666;
}

.step.active .step-circle {
    background: #1a73e8;
    color: white;
}

.step.completed .step-circle {
    background: #34a853;
    color: white;
}

.step-label {
    margin-top: 0.4rem;
    font-size: 0.75rem;
    text-align: center;
    white-space: nowrap;
}

.step-connector {
    flex: 1;
    height: 2px;
    background: #e0e0e0;
    min-width: 30px;
    margin: 0 0.5rem;
    margin-bottom: 1.2rem;
}

.step-connector.completed {
    background: #34a853;
}

.form-section {
    background: #fff;
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    padding: 2rem;
}

.form-section h2 {
    margin-top: 0;
    margin-bottom: 1.5rem;
    color: #333;
}

.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.3rem;
    font-weight: 500;
    color: #555;
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="tel"],
.form-group input[type="date"],
.form-group textarea {
    width: 100%;
    padding: 0.6rem 0.8rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 1rem;
    box-sizing: border-box;
}

.form-group textarea {
    min-height: 80px;
    resize: vertical;
}

.cover-letter-input {
    min-height: 200px !important;
}

.character-count {
    text-align: right;
    font-size: 0.85rem;
    color: #666;
    margin-top: 0.3rem;
}

.form-actions {
    display: flex;
    justify-content: space-between;
    margin-top: 1.5rem;
    gap: 1rem;
}

.btn-next, .btn-submit {
    padding: 0.7rem 1.5rem;
    background: #1a73e8;
    color: white;
    border: none;
    border-radius: 4px;
    font-size: 1rem;
    cursor: pointer;
    margin-left: auto;
}

.btn-next:hover, .btn-submit:hover {
    background: #1557b0;
}

.btn-next:disabled, .btn-submit:disabled {
    background: #93c5fd;
    cursor: not-allowed;
}

.btn-back {
    padding: 0.7rem 1.5rem;
    background: #f1f3f4;
    color: #333;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 1rem;
    cursor: pointer;
}

.btn-back:hover {
    background: #e0e0e0;
}

.btn-add {
    padding: 0.5rem 1rem;
    background: transparent;
    color: #1a73e8;
    border: 1px dashed #1a73e8;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.9rem;
    margin-top: 0.5rem;
}

.btn-add:hover {
    background: #e8f0fe;
}

.btn-remove {
    float: right;
    padding: 0.3rem 0.7rem;
    background: #fce8e6;
    color: #d93025;
    border: 1px solid #d93025;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.8rem;
}

.btn-remove:hover {
    background: #d93025;
    color: white;
}

.work-entry, .reference-entry {
    border: 1px solid #e0e0e0;
    border-radius: 6px;
    padding: 1.5rem;
    margin-bottom: 1rem;
}

.work-entry h3, .reference-entry h3 {
    margin-top: 0;
    margin-bottom: 1rem;
    color: #444;
}

.error-message {
    background: #fce8e6;
    color: #d93025;
    padding: 0.8rem 1rem;
    border-radius: 4px;
    margin-bottom: 1rem;
    border: 1px solid #f5c6cb;
}

/* Review section styles */
.review-section {
    border: 1px solid #e0e0e0;
    border-radius: 6px;
    padding: 1.2rem;
    margin-bottom: 1rem;
}

.review-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.8rem;
}

.review-header h3 {
    margin: 0;
    color: #333;
}

.edit-link {
    color: #1a73e8;
    cursor: pointer;
    font-size: 0.9rem;
    text-decoration: underline;
}

.edit-link:hover {
    color: #1557b0;
}

.review-section dl {
    display: grid;
    grid-template-columns: auto 1fr;
    gap: 0.3rem 1rem;
    margin: 0;
}

.review-section dt {
    font-weight: 500;
    color: #555;
}

.review-section dd {
    margin: 0;
    color: #333;
}

.review-work-entry, .review-reference {
    padding: 0.5rem 0;
    border-bottom: 1px solid #f0f0f0;
}

.review-work-entry:last-child, .review-reference:last-child {
    border-bottom: none;
}

.review-work-entry p, .review-reference p {
    margin: 0.2rem 0;
}

.cover-letter-preview {
    white-space: pre-wrap;
    color: #333;
}

.confirmation {
    text-align: center;
    padding: 3rem 2rem;
}

.confirmation h2 {
    color: #34a853;
}

